// KTETRA subroutine equivalent
void ktetra(int iopt, int jtype, std::vector<double>& ecpt, Eigen::MatrixXd& stiffness_matrix,
            double E, double nu, const std::vector<std::vector<double>>& node_coords) {
    // Build H matrix (4x4) for tetrahedron
    Eigen::Matrix4d H;
    H.setZero();
    H(0,0) = 1.0; H(0,1) = ecpt[7]; H(0,2) = ecpt[8]; H(0,3) = ecpt[9];  // Point 1
    H(1,0) = 1.0; H(1,1) = ecpt[11]; H(1,2) = ecpt[12]; H(1,3) = ecpt[13]; // Point 2
    H(2,0) = 1.0; H(2,1) = ecpt[15]; H(2,2) = ecpt[16]; H(2,3) = ecpt[17]; // Point 3
    H(3,0) = 1.0; H(3,1) = ecpt[19]; H(3,2) = ecpt[20]; H(3,3) = ecpt[21]; // Point 4

    // Invert H matrix
    Eigen::Matrix4d H_inv;
    double h_deter;
    if (!invert4x4(H, H_inv, h_deter)) {
        return; // Bad geometry
    }

    h_deter = std::abs(h_deter);

    // Compute material matrix G
    Matrix6d G = computeG(E, nu);

    // Compute C matrices: C[i] is 6x3, where row k of C[i] is derivative of strain component k w.r.t. displacement components
    // For linear tet: C[i] = [ dN_i/dx, 0, 0;
    //                        0, dN_i/dy, 0;
    //                        0, 0, dN_i/dz;
    //                        dN_i/dy, dN_i/dx, 0;
    //                        dN_i/dz, 0, dN_i/dx;
    //                        0, dN_i/dz, dN_i/dy ]
    // And dN_i/dx = H_inv(i,1), dN_i/dy = H_inv(i,2), dN_i/dz = H_inv(i,3)
    std::vector<Eigen::Matrix<double,6,3>> C(4);
    for (int i = 0; i < 4; ++i) {
        C[i] = Eigen::Matrix<double,6,3>::Zero();
        double dNdx = H_inv(i,1);
        double dNdy = H_inv(i,2);
        double dNdz = H_inv(i,3);
        C[i](0,0) = dNdx;
        C[i](1,1) = dNdy;
        C[i](2,2) = dNdz;
        C[i](3,0) = dNdy; C[i](3,1) = dNdx;
        C[i](4,0) = dNdz; C[i](4,2) = dNdx;
        C[i](5,1) = dNdz; C[i](5,2) = dNdy;
    }

    // Determine scaling factor
    double scale_factor = 1.0;
    if (jtype == 1) { // wedge
        if (iopt <= 6) {
            scale_factor = h_deter / 18.0;
        } else {
            scale_factor = h_deter / 36.0;
        }
    } else {
        scale_factor = h_deter / 6.0;
    }

    // Compute local 12x12 stiffness matrix for tetrahedron
    Eigen::Matrix<double,12,12> K_local = Eigen::Matrix<double,12,12>::Zero();

    // Compute all 4x4 blocks: K_local(3*i : 3*i+2, 3*j : 3*j+2) = scale * C[i]^T * G * C[j]
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            Eigen::Matrix3d K_block = scale_factor * C[i].transpose() * G * C[j];

            // Apply coordinate transformation: T^T * K_block * T
            Eigen::Matrix3d T = computeT();
            K_block = T.transpose() * K_block * T;

            // Map local node i,j to global DOF indices
            int node_i = static_cast<int>(ecpt[2+i]); // 1-based node ID
            int node_j = static_cast<int>(ecpt[2+j]);
            int g_i = 3 * (node_i - 1);
            int g_j = 3 * (node_j - 1);

            // Assemble into global matrix
            for (int r = 0; r < 3; ++r) {
                for (int c = 0; c < 3; ++c) {
                    stiffness_matrix(g_i + r, g_j + c) += K_block(r,c);
                }
            }
        }
    }
}

